Последнее сообщение пользователя:
[User]
You are a Senior Tech Lead at a top Silicon Valley startup.

You receive a PRODUCT PLAN from a product leader.
Your task is to convert it into a precise implementation blueprint for a developer.

IMPORTANT:
- PRODUCT PLAN remains the source of truth
- TECHNICAL BLUEPRINT is an implementation guide, not a replacement for the plan
- Do NOT invent onboarding, paywall, settings, auth, or premium logic unless the plan requires them
- Do NOT add features that are not supported by the plan
- Make implicit implementation requirements explicit: routing, state ownership, persistence, loading/error handling, and file responsibilities

Output ONLY valid JSON. No markdown.

Use this schema:

{
  "technicalBlueprint": {
    "appShell": {
      "routingStrategy": "How routing should be structured",
      "stateStrategy": "What belongs in app-level shared state vs page-local state",
      "persistenceStrategy": "Which localStorage or persistence keys are needed and why",
      "guardStrategy": "How semantic guards from the plan should be implemented"
    },
    "fileStructure": [
      {
        "file": "App.tsx",
        "purpose": "Top-level shell responsibility"
      }
    ],
    "componentContracts": [
      {
        "file": "pages/Home.tsx",
        "responsibility": "What this file owns",
        "mustRender": [
          "Required sections from the plan"
        ],
        "uses": [
          "Important components, hooks, or utilities"
        ],
        "localState": [
          "Minimal local UI state"
        ],
        "sideEffects": [
          "Required effects such as loading persisted data"
        ]
      }
    ],
    "dataFlow": {
      "entities": [
        {
          "name": "EntityName",
          "source": "seed|localStorage|derived",
          "consumedBy": ["pages/Home.tsx"]
        }
      ],
      "seedData": {
        "needed": false,
        "variable": "Optional constant or initializer name",
        "notes": "How seed data should be structured if required"
      }
    },
    "criticalPaths": [
      {
        "name": "Primary user flow",
        "steps": [
          "Route enters here",
          "User performs core action",
          "State updates here",
          "Guard or premium check happens here if required by plan"
        ]
      }
    ],
    "implementationRisks": [
      "Potential weak points the coder must avoid"
    ]
  }
}

[User]
PRODUCT PLAN:
{
  "id": "rhythmbloom-coach",
  "appName": "RhythmBloom Coach",
  "description": "Cycle-aware micro-recovery guide that syncs nervous-system resets with each hormonal phase.",
  "theme": "bloom",
  "targetUser": "Perimenopausal communications director balancing launch weeks with unpredictable energy and inflammation spikes.",
  "productStrategy": {
    "coreAction": "Delivers a phase-specific five-minute recovery plan calibrated to current symptoms and wearable signals.",
    "retentionLoop": "Twice-daily nudges recap progress, ask for quick check-ins, and auto-adjust the next micro-habit stack.",
    "businessModel": "subscription",
    "paywall": {
      "needed": true,
      "trigger": "After 7-day trial",
      "lockedFeature": "Unlimited adaptive phase plans with biomarker overlays and Slack coaching drops",
      "upgradeMessage": "Keep every cycle phase tuned with live biomarker overlays and coach check-ins after your 7-day calibration."
    }
  },
  "userJourney": {
    "onboarding": {
      "needed": true,
      "reason": "Requires menstrual cadence, priority symptoms, and connected devices to personalize protocols.",
      "steps": [
        {
          "question": "How regular is your current cycle length?",
          "type": "single-choice",
          "options": [
            "24-26 days",
            "27-30 days",
            "31+ days",
            "Not sure / irregular"
          ],
          "storesIn": "userProfile.cycleLength"
        },
        {
          "question": "Which outcome should we stabilize first?",
          "type": "multi-choice",
          "options": [
            "Energy across workdays",
            "Sleep depth",
            "Inflammation/bloating",
            "Mood swings"
          ],
          "storesIn": "userProfile.priority"
        },
        {
          "question": "Pick devices or labs we can sync today",
          "type": "multi-choice",
          "options": [
            "Oura Ring",
            "Whoop",
            "Dexcom Stelo",
            "Manual only"
          ],
          "storesIn": "userProfile.devices"
        }
      ],
      "completionAction": "After onboarding → navigate to / with a prebuilt phase schedule"
    },
    "firstSession": "User lands on Home seeing the current phase ribbon, a hero card summarizing readiness, and the top three five-minute practices. They tap one practice to view breath cues, mark completion, then slide into the biomarker mini-chart seeded with example data. A sticky CTA invites connecting a wearable; a chat bubble offers coach tips if more than two tasks remain.",
    "returningSession": "Returning users see a progress streak chip, compare yesterday’s symptom check-in to today’s suggestion, and get a re-sequenced micro-habit row plus reminder to schedule the next lab sync."
  },
  "layout": {
    "type": "tabs",
    "navigation": "bottom-tabs",
    "primaryColor": "rose-500"
  },
  "uxPatterns": {
    "emptyStates": true,
    "loadingSkeletons": false,
    "searchAndFilter": false,
    "animations": "subtle"
  },
  "responsiveness": {
    "primaryDevice": "mobile",
    "mobileFirst": true,
    "maxWidth": "max-w-md"
  },
  "pages": [
    {
      "path": "/onboarding",
      "name": "Onboarding",
      "file": "pages/Onboarding.tsx",
      "purpose": "Collect minimum user data to personalize the experience",
      "isMainScreen": false,
      "showInNav": false,
      "guard": "show only if !localStorage.getItem('onboarding_complete')",
      "uiSpec": "Multi-step wizard flows vertically with a gentle floral gradient header, a pill-shaped progress tracker pinned under the status bar, and copy explaining why each answer unlocks more precise recovery prescriptions. Every step shows the main question, descriptive helper text, and large tactile cards that expand to show what data will be used. Device selection step includes toggle chips plus a disclosure about manual entry; an error toast appears if no option is chosen. A sticky bottom bar hosts Back, Next, and Skip (disabled when required fields are empty). Empty-state illustrations reassure users about privacy. On compact screens, questions stack; on tablets, cards form two columns while the right side previews how answers shape the initial plan. Accessibility checklist covers 44px touch targets and voice-over labels."
    },
    {
      "path": "/",
      "name": "Home",
      "file": "pages/Home.tsx",
      "purpose": "Main workspace",
      "isMainScreen": true,
      "showInNav": true,
      "guard": "redirect to /onboarding if !onboarding_complete",
      "uiSpec": "Home opens with a top app bar showing phase name, date, and a quick-access emoji toggle for mood. Below, a hero readiness card combines gradient background, cycle day, heart-rate variability summary, and an action button labeled \"Start 5-min reset\". The plan section lists three micro-habits; each card contains duration chips, instructions, and a completion checkbox that animates with a subtle bloom. A timeline carousel shows past and upcoming phases with status dots, while the biomarker widget uses dual-line charts and dotted guidance zones. Empty-state copy invites logging first symptom if no data exists; seeded examples ensure the chart never feels blank. Sticky bottom tab bar provides Today, Library, and Settings icons. On mobile, charts become swipeable; on desktop widths, plan cards align in two columns and the chart docks right."
    },
    {
      "path": "/settings",
      "name": "Settings",
      "file": "pages/Settings.tsx",
      "purpose": "User preferences, account, subscription status",
      "isMainScreen": false,
      "showInNav": true,
      "uiSpec": "Settings uses a scrollable list divided by labeled cards: Profile shows avatar, editable pronouns, and cycle length with inline validation; Preferences includes switches for daily reminders, quiet hours, and measurement units. Subscription section displays plan badge, renewal date, a CTA to manage billing, and upgrade copy referencing premium metrics. Integrations panel shows connected devices with status pills and reconnect buttons. Data section contains export to CSV, clear symptom logs (with confirmation dialog), and privacy policy links. On empty states, placeholder icons explain benefits of connecting data. The layout keeps sticky save buttons within reach on small phones, while tablets split the view into a two-column grid with a persistent nav rail."
    }
  ],
  "authFlow": {
    "type": "supabase",
    "localFirst": false,
    "reason": "Needs secure profile sync across devices plus subscription entitlements."
  },
  "dataModel": {
    "entities": [
      {
        "name": "PhasePlan",
        "fields": "id: string, cyclePhase: enum(menstrual|follicular|ovulatory|luteal), focus: string, microActions: string[], readinessScore: number, nextCheckIn: string",
        "storage": "localStorage key: 'phasePlans'"
      },
      {
        "name": "BiomarkerLog",
        "fields": "id: string, timestamp: string, metric: string, value: number, source: string, note: string",
        "storage": "localStorage key: 'biomarkerLogs'"
      },
      {
        "name": "MicroHabit",
        "fields": "id: string, title: string, instructions: string, durationMin: number, tags: string[]",
        "storage": "localStorage key: 'microHabits'"
      }
    ],
    "seedData": {
      "needed": true,
      "reason": "Preloaded plans keep the workspace informative before personal data syncs.",
      "examples": [
        "PhasePlan: id=plan_menstrual_reset, cyclePhase=menstrual, focus=\"Lower cortisol\", microActions=[\"Box breathing\", \"Warm magnesium drink\", \"Gentle fascia roll\"], readinessScore=62, nextCheckIn=\"2026-04-12T08:00:00Z\"",
        "BiomarkerLog: id=log_hrv_demo, timestamp=\"2026-04-10T06:30:00Z\", metric=\"HRV\", value=54, source=\"Oura\", note=\"Post-meeting\"",
        "MicroHabit: id=habit_spine_wave, title=\"Desk spine waves\", instructions=\"3 sets of 8 slow articulations\", durationMin=4, tags=[\"movement\",\"spine\"]"
      ]
    },
    "sharedState": "App.tsx stores userProfile, phasePlans, biomarkerLogs, paywallState, and connectedDevices context."
  },
  "criticalUiRules": [
    "Color-code every phase consistently across cards, charts, and notifications.",
    "Never surface more than three active micro-habits at once to prevent overload."
  ],
  "shadcnComponents": [
    "Button",
    "Card",
    "Tabs",
    "Progress",
    "Badge",
    "Switch"
  ],
  "icons": [
    "Heart",
    "Calendar",
    "Settings"
  ],
  "marketContext": "Cycle syncing, nervous-system training, and hormone personalization lead 2026 wellness priorities, proving appetite for adaptive perimenopause tools. ([whowhatwear.com](https://www.whowhatwear.com/wellness-trends-2026?utm_source=openai))",
  "targetAudience": "Anastasia, 47-year-old VP of Communications in Chicago managing studio launches plus perimenopause symptoms.",
  "painPoint": "She lacks a lightweight, science-backed routine that adapts to daily hormonal shifts without overwhelming checklists.",
  "competitorGap": "Generic wellness apps treat women’s data as static, while hormone clinics gate insights behind expensive consults.",
  "generatedAt": "2026-04-11T00:04:39.119Z"
}

